/** A user watching a person on a sheet; watches are kept in the order they were started (by id). */
@Entity
@Table(name = "person_watch")
public class Watch {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
