        watches.saveAndFlush(new Watch(sheetId, personId, user));
        audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
    }

    /** Stop watching a person as the user; refused when they do not watch them. */
    @Transactional
    public void unwatch(String sheetId, String user, long personId) {
        Person person = person(sheetId, personId);
        Watch watch = watches.findBySheetIdAndPersonIdAndUser(sheetId, personId, user)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
                        "You do not watch " + person.getName() + "."));
        watches.delete(watch);
        watches.flush();
        audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
    }

    /**
     * Notify each user watching the person that their claim of this number was settled, approved or
     * re-settled, in the order they started watching, once the change is committed.
     */
    public void notifyWatchers(String sheetId, String user, Person person, String number) {
        for (Watch watch : watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, person.getId())) {
            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
                    + " person=" + person.getName() + " number=" + number);
        }
    }

    private Person person(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
    }
}
import { Component, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { People } from '../people/people';
import { Settings } from '../settings/settings';

// The one screen: sign in by typing a name, then load a sheet by id and work on its people.
@Component({
  selector: 'app-home',
  imports: [People, Settings],
  template: `
    @if (session.user(); as user) {
      <section aria-label="Session">
        <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
        <form (submit)="load($event)">
          <label for="sheet-id-input">Sheet id</label>
          <input
            id="sheet-id-input"
            data-testid="sheet-id-input"
            [value]="sheetInput()"
            (input)="sheetInput.set(value($event)); sheetError.set(null)"
          />
          <button type="submit" data-testid="sheet-load">Load</button>
          @if (sheetError(); as error) {
            <p role="alert" data-testid="sheet-error">{{ error }}</p>
          }
        </form>
        @if (session.sheet(); as sheet) {
          <p>Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></p>
          <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
          <form (submit)="saveToday($event)">
            <label for="sheet-today-input">Change today</label>
            <input
              id="sheet-today-input"
              type="date"
              data-testid="sheet-today-input"
              [value]="todayInput()"
              (input)="todayInput.set(value($event)); sheetError.set(null)"
            />
            <button type="submit" data-testid="sheet-today-save">Save today</button>
          </form>
          <app-settings />
          <app-people />
        }
        <p data-testid="home-empty">Nothing here yet.</p>
      </section>
    } @else {
      <form aria-label="Sign in" (submit)="signIn($event)">
        <label for="signin-name">Your name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set(value($event)); signinError.set(null)"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError(); as error) {
          <p role="alert" data-testid="signin-error">{{ error }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly todayInput = signal('');
  protected readonly signinError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  /** A today change is waiting for its answer: a second submit meanwhile is ignored. */
  private savingToday = false;

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected signIn(event: Event): void {
    event.preventDefault();
    const name = this.nameInput().trim();
    if (!name) {
      this.signinError.set('Type your name to sign in.');
      return;
    }
    this.signinError.set(null);
    this.session.signIn(name);
  }

  protected async load(event: Event): Promise<void> {
    event.preventDefault();
    this.sheetError.set(null);
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Type a sheet id to load.');
      return;
    }
    try {
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set(`Sheet "${id}" could not be loaded.`);
    }
  }

  protected async saveToday(event: Event): Promise<void> {
    event.preventDefault();
    if (this.savingToday) return;
    this.sheetError.set(null);
    const date = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.sheetError.set('Pick a date for today.');
      return;
    }
    this.savingToday = true;
    try {
      await this.session.setToday(date);
    } catch {
      this.sheetError.set(`Today could not be changed to ${date}.`);
    } finally {
      this.savingToday = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** A setting's value from a date (yyyy-mm-dd); from null for its starting value, before every from-date. */
export interface DatedValue {
  from: string | null;
  value: string;
}

/**
 * The value a dated setting has in force on a date (yyyy-mm-dd): the one with the latest from-date
 * on or before it, else the starting value (the one with no from-date), else `start`.
 */
export function valueOn(history: DatedValue[], date: string, start: string): string {
  let best: DatedValue | null = null;
  for (const d of history) {
    if (d.from !== null && d.from > date) continue;
    if (best === null || (d.from !== null && (best.from === null || d.from > best.from))) best = d;
  }
  return best === null ? start : best.value;
}

export interface SheetView {
  id: string;
  /** The sheet's today (yyyy-mm-dd): every date-dependent decision and default date uses it. */
  today: string;
  /** The sheet's floor in force on its today, with two decimals. */
  floor: string;
  /** The sheet's terms in force on its today, in days. */
  terms: number;
  /** The sheet's late percent in force on its today, with two decimals. */
  latePct: string;
  /** The sheet's policy date (yyyy-mm-dd); null when blank, the sheet's today then being the policy date. */
  policyDate: string | null;
  /** The sheet's cap in force on its today, with two decimals: a person's due-total is at most it; null when there is none. */
  cap: string | null;
  /** The floor's values by from-date, its starting value first. */
  floorHistory: DatedValue[];
  /** The late percent's values by from-date, its starting value first. */
  latePctHistory: DatedValue[];
}

// The signed-in user (a typed name, no password) and the active sheet. Everything else in the
// app is kept per sheet, so features read the active sheet id from here.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheet = signal<string | null>(null);
  /** The active sheet's today; features use it, never the real clock. */
  readonly today = signal<string | null>(null);
  /** The active sheet's floor in force on its today, with two decimals. */
  readonly floor = signal('1.00');
  /** The active sheet's floor by from-date: a claim's live due is at least the one in force on its date. */
  readonly floorHistory = signal<DatedValue[]>([]);
  /** The active sheet's terms in force on its today, in days. */
  readonly terms = signal(14);
  /** The active sheet's late percent in force on its today, with two decimals. */
  readonly latePct = signal('0.00');
  /**
   * The active sheet's late percent by from-date: an overdue claim gains the one in force on its date
   * of its figure every full 30 days.
   */
  readonly latePctHistory = signal<DatedValue[]>([]);
  /** The active sheet's policy date (yyyy-mm-dd); empty when blank (the sheet's today is then the policy date). */
  readonly policyDate = signal('');
  /** The active sheet's cap in force on its today, with two decimals: a person's due-total is at most it; empty when there is none. */
  readonly cap = signal('');
  /** Counts sheet loads, so features re-read the store even when the same id is loaded again. */
  readonly loads = signal(0);

  signIn(name: string): void {
    this.user.set(name);
  }

  /** Load a sheet by id from the store; an id never used before starts an empty sheet. */
  async loadSheet(id: string): Promise<void> {
    const view = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null),
    );
    this.show(view);
    this.loads.update((n) => n + 1);
  }

  /** Change the active sheet's today in the store. */
  async setToday(date: string): Promise<void> {
    const id = this.sheet();
    if (!id) throw new Error('No sheet is loaded.');
    const view = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today: date }),
    );
    this.show(view);
  }

  private show(view: SheetView): void {
    this.sheet.set(view.id);
    this.today.set(view.today);
    this.floor.set(view.floor);
    this.terms.set(view.terms);
    this.latePct.set(view.latePct);
    this.floorHistory.set(view.floorHistory);
    this.latePctHistory.set(view.latePctHistory);
    this.policyDate.set(view.policyDate ?? '');
    this.cap.set(view.cap ?? '');
  }
}
import { HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/** Tells the server who is signed in on every request, so changes are recorded against them. */
export const signedInInterceptor: HttpInterceptorFn = (req, next) => {
  const user = inject(Session).user();
  return next(user ? req.clone({ setHeaders: { 'X-User': encodeURIComponent(user) } }) : req);
};
